#!/usr/bin/env python3
"""Generate public/.htaccess from scripts/redirects.json.

Run after editing redirects.json:  python3 scripts/make_htaccess.py
Next.js copies public/.htaccess into out/ on build, and Hostinger (LiteSpeed/Apache) reads it.
"""
import json
from pathlib import Path

root = Path(__file__).resolve().parent.parent
redirects = json.loads((root / "scripts" / "redirects.json").read_text())

lines = [
    "# Generated by scripts/make_htaccess.py. Do not edit by hand.",
    "RewriteEngine On",
    "",
    "# Force HTTPS",
    "RewriteCond %{HTTPS} off",
    "RewriteRule ^(.*)$ https://%{HTTP_HOST}/$1 [R=301,L]",
    "",
    "# Old WordPress URLs",
]
for old, new in redirects.items():
    lines.append(f"RedirectMatch 301 ^{old.rstrip('/')}/?$ {new}")
lines += [
    "",
    "# WordPress taxonomy archives",
    "RedirectMatch 301 ^/(category|tag)/.*$ /blog/",
    "",
    "ErrorDocument 404 /404.html",
    "",
]
(root / "public" / ".htaccess").write_text("\n".join(lines))
print(f"wrote public/.htaccess with {len(redirects) + 1} rules")
